import heapq

class DisjointSet:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        elif self.rank[x_root] > self.rank[y_root]:
            self.parent[y_root] = x_root
        else:
            self.parent[y_root] = x_root
            self.rank[x_root] += 1
        return True

def kruskals(n, edges):
    edges.sort()
    mst = []
    dsu = DisjointSet(n)
    for w, u, v in edges:
        if dsu.union(u, v):
            mst.append((u, v, w))
    return mst

def dijkstras(n, edges):
    graph = [[] for _ in range(n)]
    for w, u, v in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    dist = [float('inf')] * n
    dist[0] = 0
    pq = [(0, 0)]
    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > d + w:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))
    return dist

def prims(n, edges):
    graph = [[] for _ in range(n)]
    for w, u, v in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    visited = [False] * n
    mst = []
    pq = [(0, 0, -1)]
    while pq:
        w, u, p = heapq.heappop(pq)
        if visited[u]:
            continue
        visited[u] = True
        if p != -1:
            mst.append((p, u, w))
        for v, w in graph[u]:
            if not visited[v]:
                heapq.heappush(pq, (w, v, u))
    return mst

n = 3
edges = [(1, 0, 1), (2, 1, 2), (3, 0, 2)]
print("Kruskal's MST:", kruskals(n, edges))
print("Dijkstra's distances:", dijkstras(n, edges))
print("Prim's MST:", prims(n, edges))

