import re
from collections import Counter

def extract_info(text):
    info = {}

    # Identify entities
    entities = {
        "name": r"My name is (\w+)",
        "email": r"Email: ([\w.]+@[\w.]+)",
        "location": r"from ([\w\s]+)\.",
    }

    for key, pattern in entities.items():
        match = re.search(pattern, text)
        if match:
            info[key] = match.group(1)

    return info

def word_frequency(text):
    words = re.findall(r'\b\w+\b', text.lower())
    return Counter(words)

def find_mentions(text, term):
    regex = r"\b" + re.escape(term) + r"\b"
    return len(re.findall(regex, text, re.IGNORECASE))

text = "My name is John. Email: john@example.com. I'm from New York. Hello hello hello!"

print(extract_info(text))
print(word_frequency(text))
print(find_mentions(text, "hello"))

