from fastapi import FastAPI, Request, HTTPException
import json
from utils.database import get_database_connection
from utils.ratelimit import check_rate_limit

app = FastAPI()

@app.post("/draft-share")
async def draft_share(request: Request):
    if check_rate_limit(request):
        return HTTPException(status_code=429, detail="Rate limit reached")

    req = await request.json()
    draft_id = req.get("draft_id")

    if not draft_id:
        return HTTPException(status_code=400, detail="Missing draft_id")

    connection = get_database_connection(role="draft_writer")
    cursor = connection.cursor()
    cursor.execute(f"SELECT * FROM drafts WHERE id = {draft_id}")
    draft = cursor.fetchone()

    return {"success": True, "draft": draft}
